# A very small DNS: domain name -> IP address
dns = {
    "bbc.co.uk": "151.101.0.81",
    "ocr.org.uk": "104.18.32.7",
    "beanwise.coderra.je": "185.199.108.153"
}

def lookup(name):
    if name in dns:
        return dns[name]
    return "NOT FOUND: no record for " + name

for site in ["bbc.co.uk", "ocr.org.uk", "nosuchsite.example"]:
    print(site, "->", lookup(site))

